INSERT INTO rbac_permission(code,name,module,description,tenant_id) SELECT 'agent:tool:approval.genericTask.participants.query','查询通用任务协作候选','AI 能力','受控通用任务协作，校验租户、当前处理人、版本及资格',id FROM tenant WHERE code='DEFAULT' ON CONFLICT(code) DO NOTHING;
INSERT INTO rbac_role_permission(tenant_id,role_code,permission_code) SELECT DISTINCT a.tenant_id,a.role_code,'agent:tool:approval.genericTask.participants.query' FROM rbac_role_permission a JOIN rbac_role_permission r ON r.tenant_id=a.tenant_id AND r.role_code=a.role_code AND r.permission_code='todo:read' WHERE a.permission_code='approval:act' ON CONFLICT DO NOTHING;
